import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const marker = "// @vunapos-release-signing";
const defaultBuildFile = resolve("android/app/build.gradle");

export function releaseConfigurationBlock() {
  return `${marker}
// This is applied after Expo prebuild from a version-controlled script. Release
// tasks must never silently use the debug keystore generated by React Native.
def vunaposReleaseVersionCode = (findProperty('VUNAPOS_VERSION_CODE') ?: '1').toInteger()
if (vunaposReleaseVersionCode <= 0) {
    throw new GradleException('VUNAPOS_VERSION_CODE must be a positive integer.')
}
def vunaposReleaseVersionName = findProperty('VUNAPOS_VERSION_NAME') ?: '1.0.0'
def vunaposReleaseStoreFile = findProperty('VUNAPOS_RELEASE_STORE_FILE') ?: System.getenv('VUNAPOS_RELEASE_STORE_FILE')
def vunaposReleaseStorePassword = findProperty('VUNAPOS_RELEASE_STORE_PASSWORD') ?: System.getenv('VUNAPOS_RELEASE_STORE_PASSWORD')
def vunaposReleaseKeyAlias = findProperty('VUNAPOS_RELEASE_KEY_ALIAS') ?: System.getenv('VUNAPOS_RELEASE_KEY_ALIAS')
def vunaposReleaseKeyPassword = findProperty('VUNAPOS_RELEASE_KEY_PASSWORD') ?: System.getenv('VUNAPOS_RELEASE_KEY_PASSWORD')
def vunaposHasReleaseSigning = [vunaposReleaseStoreFile, vunaposReleaseStorePassword, vunaposReleaseKeyAlias, vunaposReleaseKeyPassword].every { it }
def vunaposReleaseTaskRequested = gradle.startParameter.taskNames.any { it.toLowerCase().contains('release') }
if (vunaposReleaseTaskRequested && !vunaposHasReleaseSigning) {
    throw new GradleException('Release signing is required. Provide VUNAPOS_RELEASE_STORE_FILE, VUNAPOS_RELEASE_STORE_PASSWORD, VUNAPOS_RELEASE_KEY_ALIAS, and VUNAPOS_RELEASE_KEY_PASSWORD.')
}
afterEvaluate {
    android.defaultConfig.versionCode = vunaposReleaseVersionCode
    android.defaultConfig.versionName = vunaposReleaseVersionName
    def vunaposReleaseSigning = android.signingConfigs.maybeCreate('release')
    vunaposReleaseSigning.storeFile = file(vunaposReleaseStoreFile ?: 'missing-release-keystore')
    vunaposReleaseSigning.storePassword = vunaposReleaseStorePassword
    vunaposReleaseSigning.keyAlias = vunaposReleaseKeyAlias
    vunaposReleaseSigning.keyPassword = vunaposReleaseKeyPassword
    android.buildTypes.getByName('release').signingConfig = vunaposReleaseSigning
}
`;
}

export async function prepareAndroidRelease(buildFile = defaultBuildFile) {
  const source = await readFile(buildFile, "utf8");
  if (source.includes(marker)) return false;
  await writeFile(buildFile, `${source.trimEnd()}\n\n${releaseConfigurationBlock()}`);
  return true;
}

if (process.argv[1] === new URL(import.meta.url).pathname) {
  const buildFile = process.argv[2] ? resolve(process.argv[2]) : defaultBuildFile;
  const changed = await prepareAndroidRelease(buildFile);
  console.log(`${changed ? "Prepared" : "Already prepared"} Android release configuration: ${buildFile}`);
}
